facts.body_text:
const read = this.progress
if (this.heldProgress?.read !== read) this.heldProgress = { read, clients: read.map(progress => new FidelityProgressClient(progress, this)) }
return this.heldProgress.clients

if (!this.next || this.isLocked) return false
// Opening the report while violations hold the fidelity is done on the board, so it needs no chat.
return this.nextProgress?.state === 'violations' || this.page.chat.canSend

own = [card for card in self._board.cards if card.column is self and not card.is_stacked]
placed = self._board.order_in(self)
return sorted(own, key=lambda card: placed.index(card.key) if card.key in placed else len(placed))

if self._session.is_closed:
    return self._board.column(COMPLETE_COLUMN)
furthest_back = self._furthest_back_child_stage
if furthest_back is not None:
    return furthest_back
return self.work.stage_worked_since_latest_move or self.marks.moved_into or self._board.stages[0]

column = self.column
if not isinstance(column, Stage):
    return False
children_here = [child for child in self.children if child.column is column]
if children_here:
    return all(child.is_done for child in children_here)
marked = self.marks.latest_in(column)
if marked is not None:
    return marked == MARKED_DONE
return all(progress.is_done for progress in self.work.enabled if progress.stage is column)

column = self.column
stages = self._board.stages
if self.is_done or column not in stages:
    return None
reached = stages[: stages.index(column) + 1]
return next((progress for progress in self.work.enabled if progress.stage in reached and not progress.is_done), None)

entries = self._ticket.session.log.entries
moves = [index for index, entry in enumerate(entries) if entry.verb == MOVED_INTO]
since = entries[moves[-1] + 1:] if moves else entries
for entry in reversed(since):
    if entry.verb not in (GENERATE, VALIDATE):
        continue
    stage = next((progress.stage for progress in self.enabled if entry.names(progress.fidelity)), None)
    if stage is not None:
        return stage
return None

name = self._recorded_stage
if name is None:
    moved = self._ticket.session.log.latest(MOVED_INTO)
    name = moved.stage if moved is not None else ""
return next((stage for stage in self._ticket.board.stages if stage.name == name), None)

if self.is_done:
    return "done"
if self._has_violations:
    return "violations"
return "in_progress" if self._done_actions else "not_started"

states = {action: "done" if action in self._done_actions else "to_do" for action in self._stage.steps}
if self._has_violations:
    states[VALIDATE] = "in_progress"
return ActionStates(states)

if destination in self.files or self._checked is None:
    return
destination.write_text(self._checked.text, encoding="utf-8")

judged = [
    (fidelity, format)
    for fidelity, format in zip(self._fidelities, self._formats)
    if (bool(self.files) and fidelity.is_judged_on_graph) == on_graph
]
return "; ".join(f"{format}: {', '.join(self.edited or fidelity.output_paths().get(format, []))}" for fidelity, format in judged)

if self.prefixes and self._named in (None, True) and self._fidelities:
    return [self._built_at(reports.graph_file())]
if self._named is True:
    return self._session_saved()
return self._read_named()

others = [
    self.session.path_named(path)
    for fidelity, checked in zip(self._fidelities, self._formats)
    for format, paths in fidelity.output_paths().items()
    if format != checked
    for path in paths
    if "{" not in path
]
return {path.relative_to(self.session.work_root).as_posix() for path in others if self.session.session_files.in_root(path)}

declared = [path for fidelity, checked in zip(self._fidelities, self._formats) for path in fidelity.output_paths().get(checked, [])]
found = [self.session.path_named(path) for path in declared if "{" not in path]
folders = {path.parent if path.is_file() else path for path in found if path.exists()}
return sorted(str(folder) for folder in folders if self.session.session_files.in_root(folder))

const names = new Set(this.tickets.map(ticket => ticket.name))
const earlierHeld = before.backlogItems.map(item => item.ticket)
const held = this.backlogItems.map(item => item.ticket)
return before.tickets
  .filter(ticket => !names.has(ticket.name) && held.includes(ticket.name) && !earlierHeld.includes(ticket.name))
  .map(ticket => `${ticket.title} moved to Backlog`)

const earlier = new Map(before.tickets.map(ticket => [ticket.name, ticket]))
const named = this.tickets.map(ticket => ticket.name)
const isUnique = (ticket: TicketClient) => named.indexOf(ticket.name) === named.lastIndexOf(ticket.name)
const changes = this.tickets.flatMap(ticket => {
  const was = earlier.get(ticket.name)
  return was && isUnique(ticket) ? changesOf(was, ticket) : []
})
return [...changes, ...this.returnsSince(before)]

const border = ticket.isActive ? ACTIVE_BORDER_WIDTH : 1
const span = spot === 'only' ? `100% + ${2 * (9 + border)}px` : `200% + ${4 * border + 26}px`
return { width: `calc(${span})`, top: -border, left: opensLeft ? 'auto' : -border, right: opensLeft ? -border : 'auto', opensLeft }

const { page, state } = useBoard()
const isOpen = state.openCard === ticket.name
return (
  <button className="expand-mark card-mark" aria-label={`Actions for ${ticket.title}`} aria-expanded={isOpen} onClick={withoutSelecting(() => page.cards.toggle(ticket))}>
    {isOpen ? '▴' : '▾'}
  </button>
)

const { page, state } = useBoard()
const [skill, setSkill] = useState('')
return (
  <>
    <CardMarkView ticket={ticket} />
    <div className="ticket-title-line">
      <div className="ticket-title">{ticket.title}</div>
      {ticket.chat.isOpening ? <span className="progress-wheel" role="status" title="Opening its chat in the Claude app" aria-label="Opening its chat" /> : null}
      {ticket.canOpenChat && !ticket.chat.isOpening ? (
        <SessionActionView action="chat" label={`Open the chat of ${ticket.title}`} hint="Open its chat: its worktree and a new chat in the Claude app" isOff={false} onPress={() => ticket.openChat()} />
      ) : null}
      <SplitActionView ticket={ticket} />
    </div>
    <div className="ticket-meta">{ageOf(state.now, ticket.lastActivity)}</div>
    <SegmentsView ticket={ticket} stage={stage} onSkill={setSkill} />
    {skill ? <div className="card-skill">{skill}</div> : null}
    {ticket.workIn(stage)?.hasViolations ? (
      <button className="violations-link card-violations" onClick={withoutSelecting(() => page.panels.openReport(ticket, null))}>
        violations
      </button>
    ) : null}
    <div className="card-files">
      <SessionActionsView ticket={ticket} />
      <FileViewsView ticket={ticket} progress={ticket.progressIn(stage)} />
    </div>
  </>
)

const { page } = useBoard()
const cannotFill = useCannotFill(ticket)
return (
  <span className="file-views">
    <SessionActionView action="next" label={ticket.runNextLabel} hint={ticket.runNextHint} isOff={!ticket.canRunNext} onPress={() => ticket.runNext()} />
    <SessionActionView action="handoff" label="Handoff" hint="Write a handoff for this session" isOff={cannotFill} onPress={() => ticket.fillHandoff()} />
    {ticket.isOpen ? (
      <SessionActionView action="close" label="Close" hint={ticket.closeHint} isOff={false} onPress={() => ticket.startClose()} />
    ) : ticket.isMain ? null : (
      <SessionActionView action="activate" label="Activate" hint="Open this ticket in its own worktree" isOff={ticket.isClosed} onPress={() => page.activation.activate(ticket)} />
    )}
  </span>
)

useEffect(() => {
  const open = card.current
  const grid = open?.closest<HTMLElement>('.column-grid')
  if (!open || !grid) return
  const reach = () => {
    grid.style.minHeight = `${open.getBoundingClientRect().bottom - grid.getBoundingClientRect().top + ROOM_BELOW_OPEN_CARD}px`
  }
  const watcher = new ResizeObserver(reach)
  watcher.observe(open)
  reach()
  return () => {
    watcher.disconnect()
    grid.style.minHeight = ''
  }
}, [card])

const { page, state } = useBoard()
const card = useRef<HTMLDivElement>(null)
const { opensLeft, ...place } = openCardPlace(ticket, spot, page.board.opensLeft(ticket))
// The card scrolls back into view whenever one of its bars opens or closes, since the card grows or shrinks with it.
const openPlaces = state.tiles
  .filter(tile => tile.ticket.name === ticket.name)
  .map(tile => tile.place)
  .join(' ')
// Braces matter: newer browsers return a promise from scrollIntoView, and React would call it as the effect's cleanup.
useEffect(() => {
  card.current?.scrollIntoView({ block: 'nearest', inline: 'nearest' })
}, [openPlaces])
useColumnsReachOpenCard(card)
return (
  <div ref={card} className={opensLeft ? 'card-open grows-left' : 'card-open'} data-open-card={ticket.name} style={{ ...place, borderColor: borderColorOf(ticket), borderWidth: ticket.isActive ? ACTIVE_BORDER_WIDTH : 1 }}>
    <CardFaceView ticket={ticket} stage={stage} />
    {ticket.progressIn(stage).map(progress => (
      <TileView key={progress.fidelity.slug} ticket={ticket} stage={stage} progress={progress} hasPracticeChip opensOnHover />
    ))}
  </div>
)

const { page, state } = useBoard()
const stage = page.board.stageOf(ticket)
const isSelected = page.board.selectedTicket?.address === ticket.address
const [isTakingChild, setTakingChild] = useState(false)
if (!stage) return null
// Every card drags, locked or not: Active session only keeps commands to the active session's chat, and a move runs
// nothing in a chat. An opened card closes when the drag ends.
const isDraggable = true
const dragStarted = (event: DragEvent) => {
  event.dataTransfer.setData('text/plain', ticket.name)
  event.dataTransfer.effectAllowed = 'move'
  page.store.change({ dragged: ticket.address })
}
const dragEnded = () => page.store.change(current => ({ dragged: null, openCard: current.openCard === ticket.name ? null : current.openCard }))
// Read when each event arrives, not from the last drawing: a quick drag reaches the card before the page redraws.
const draggedTicket = () => page.board.tickets.find(entry => entry.address === page.store.state.dragged)
const takes = () => {
  const dragged = draggedTicket()
  return dragged !== undefined && ticket.canTakeAsChild(dragged)
}
const draggedOver = (event: DragEvent) => {
  if (!takes()) return
  event.preventDefault()
  event.stopPropagation()
  setTakingChild(true)
}
// The card takes the drop, so the list under it does not move the ticket to its column as well.
const dropped = (event: DragEvent) => {
  setTakingChild(false)
  const dragged = draggedTicket()
  if (!dragged || !ticket.canTakeAsChild(dragged)) return
  event.preventDefault()
  event.stopPropagation()
  page.store.change({ dragged: null })
  void ticket.takeAsChild(dragged)
}
return (
  <div
    className={['ticket-card', ticket.isActive ? 'is-active' : '', state.dragged === ticket.address ? 'is-dragged' : '', isTakingChild ? 'is-drop-over' : ''].filter(Boolean).join(' ')}
    data-ticket={ticket.name}
    draggable={isDraggable}
    onDragStart={dragStarted}
    onDragEnd={dragEnded}
    onDragOver={draggedOver}
    onDragLeave={() => setTakingChild(false)}
    onDrop={dropped}
    onClick={() => ticket.choose()}
    style={{ borderColor: borderColorOf(ticket, isSelected), borderWidth: ticket.isActive ? ACTIVE_BORDER_WIDTH : 1 }}
  >
    {/* Chrome starts no drag on a button, and this one covers the card, so it carries the card's drag. */}
    <button className="card-hit" aria-label={`Show ${ticket.title}`} draggable={isDraggable} />
    <CardFaceView ticket={ticket} stage={stage} />
    {state.openCard === ticket.name ? <OpenCardView ticket={ticket} stage={stage} spot={spot} /> : null}
  </div>
)

const read = await Promise.all(progress.map(entry => entry.files()))
if (read.some(files => !files)) return null
return Object.fromEntries(progress.map((entry, index) => [entry.fidelity.slug, read[index]!]))

if (this.page.board.columnNamed(edge)?.isBacklog) await this.moveTo(edge, false)
else if (this.isOpen) await this.page.activation.startClosing(this)
else await this.moveNext()

this.select()
const found = this.chat.found
if (found) this.page.chat.choose(found.id)

await this.page.reader.refresh()
if (moved) await this.page.cards.follow(this.page.ticket(moved.toJSON()))
return moved

await this.page.reader.refresh()
if (!moved) return null
if (isBacklogItem(moved)) this.release(moved)
else await this.page.cards.follow(this.page.ticket(moved))
return moved

const next = this.nextProgress
if (!next) return
if (next.state === 'violations') return this.page.panels.openReport(this, next)
const command = next.commands[this.nextAction] ?? ''
if (this.nextAction !== 'generate') return this.chat.fill(command)
await this.chat.command(command)

shared = self._shared
shared["wip_limits"] = {**shared.get("wip_limits", {}), stage.name: limit}
JsonFile(self.file).write(shared)

shared = self._shared
shared["order"] = {**shared.get("order", {}), column.name: list(keys)}
JsonFile(self.file).write(shared)

repository = self._repo.main_clone
folder = self.sessions.folder
if not repository.branch_named(repository.default_branch).is_checked_out or not folder.is_dir():
    return
if not repository.is_dirty(folder):
    return
repository.commit([str(folder)], message, untracked=True)
if repository.has_origin:
    repository.push_upstream()

root = self._repo.root
workpath = (root / path).resolve() if path else root
return self.ticket_of(self.sessions.create(title, workpath, title=title, scope=scope, parent=parent))

held: dict[str, list[Ticket]] = {}
for ticket in self.tickets:
    if ticket.session.parent:
        held.setdefault(ticket.session.parent, []).append(ticket)
return held

repo = self._board.repo
if not repo.is_clone:
    return {}
return {tree.branch: tree for tree in repo.worktrees if tree.branch is not None}

keys = [shown.key for shown in self.cards]
for named in (card, other):
    if named.key not in keys:
        raise CardNotInColumnError(named.key, self.name)
if card.key == other.key:
    return self
keys.remove(card.key)
keys.insert(keys.index(other.key), card.key)
self._board.keep_order(self, keys)
return self

self._refuse_moving_a_parent()
column = self.column
if not isinstance(column, Stage):
    return self
if not self.is_done:
    return self.marks.mark(MARKED_DONE, column)
following = column.next_stage
if following is None and self.is_main:
    return self
return self.marks.enter(following) if following else self.close()

self._refuse_moving_a_parent()
column = self.column
if not isinstance(column, Stage):
    reopened, final = self._board.ticket_of(self._session.reopen()), self._board.stages[-1]
    reopened.marks.enter(final)
    return reopened.marks.mark(MARKED_DONE, final)
if self.is_done:
    return self.marks.mark(MARKED_IN_PROGRESS, column)
earlier = column.previous_stage
if earlier is None and self.is_main:
    return self
return self.marks.place(earlier, MARKED_DONE) if earlier else self._return_to_backlog()

self._refuse_moving_a_parent()
if stage == BACKLOG_COLUMN:
    return self._return_to_backlog()
target = self._board.stage(stage)
moved = self if isinstance(self.column, Stage) else self._board.ticket_of(self._session.reopen())
return moved.marks.place(target, MARKED_DONE if done else MARKED_IN_PROGRESS)

column = self.column
reports = [entry.report() for entry in self.progress if entry.has_violations and entry.stage is column]
return Report.from_reports(self._session.from_project(self._session.reports_folder), reports)

if self.parent is None:
    raise NotAChildError(self.name)
self._session.mark_pulled_out()
return self._saved(f"pull {self.name} out of {self._session.parent}")

if parent is not None and self.name in [parent.name, *(ancestor.name for ancestor in parent.ancestors)]:
    raise ParentLoopError(self.name, parent.name)
self._session.set_parent(parent.session if parent is not None else None)
return self._saved(f"give {self.name} the parent {parent.name if parent is not None else 'none'}")

found = next(((stage, fidelity) for stage, fidelity in self._required if fidelity.slug == slug), None)
if found is None:
    raise FidelityNotFoundError(slug, f"ticket {self._ticket.name!r}")
stage, fidelity = found
return FidelityProgress.from_log(fidelity, stage, self._ticket.session.log.entries, self._ticket)

if self._ticket.column is not stage:
    self._write(MOVED_INTO, stage)
return self.mark(mark, stage)

if not every:
    return cls({action: "to_do" for action in (GENERATE, VALIDATE)})
taken = every[0]
for states in every[1:]:
    taken = taken._with(states)
return taken
